def choose_move(observation):
    # Defensive extraction with defaults
    x = observation.get("player_x", observation.get("x", 0))
    y = observation.get("player_y", observation.get("y", 0))

    target = None
    candidates = []

    def push(x_key, y_key):
        tx = observation.get(x_key, None)
        ty = observation.get(y_key, None)
        if tx is not None and ty is not None:
            candidates.append((tx, ty))

    push("resource_x", "resource_y")
    push("evader_x", "evader_y")
    push("opponent_x", "opponent_y")
    push("beacon_x", "beacon_y")
    push("goal_x", "goal_y")
    push("target_x", "target_y")

    for key_pair in [
        ("resource_x", "resource_y"),
        ("evader_x", "evader_y"),
        ("opponent_x", "opponent_y"),
        ("beacon_x", "beacon_y"),
        ("goal_x", "goal_y"),
        ("target_x", "target_y"),
    ]:
        if key_pair[0] in observation and key_pair[1] in observation:
            candidates.append((observation.get(key_pair[0]), observation.get(key_pair[1])))

    if candidates:
        best = None
        best_dist = None
        for tx, ty in candidates:
            if tx is None or ty is None:
                continue
            dist = abs(tx - x) + abs(ty - y)
            if best_dist is None or dist < best_dist:
                best = (tx, ty)
                best_dist = dist
        if best is not None:
            target = best

    if target is not None:
        tx, ty = target
        dx = 0 if tx == x else (1 if tx > x else -1)
        dy = 0 if ty == y else (1 if ty > y else -1)
        if dx in (-1, 0, 1) and dy in (-1, 0, 1):
            return [dx, dy]

    if x != 0 or y != 0:
        dx = -1 if x > 0 else (1 if x < 0 else 0)
        dy = -1 if y > 0 else (1 if y < 0 else 0)
        if dx != 0 or dy != 0:
            return [dx, dy]

    return [-1, -1]
